# NOTICE: This file was generated by an LLM coding system.
"""Turn the lecture notebooks' slides-only code cells into text, in place.

    python3 slides_only.py NOTEBOOK.ipynb [...]

build.sh runs this on the staged copies of docs/slides/week*.ipynb. A deck marks a chunk `#| tags: [slides-only]` when it needs a library Pyodide doesn't ship (plotnine, seaborn) or a result from such a chunk; in the Yard that cell would only raise an error, so it becomes a markdown cell showing the code. The downloadable notebooks keep it as code.
"""

import json
import sys

NOTE = "*Slides only for now: this cell needs a library the Python Yard doesn't have yet (plotnine or seaborn), or a result from a cell that does, so it is shown here as text.*"


def main(paths):
    for path in paths:
        with open(path, encoding="utf-8") as f:
            nb = json.load(f)
        n = 0
        for cell in nb["cells"]:
            if cell["cell_type"] != "code" or "slides-only" not in cell.get("metadata", {}).get("tags", []):
                continue
            code = "".join(cell["source"])
            cell.pop("outputs", None)
            cell.pop("execution_count", None)
            cell["cell_type"] = "markdown"
            cell["source"] = f"{NOTE}\n\n```python\n{code}\n```"
            n += 1
        with open(path, "w", encoding="utf-8") as f:
            json.dump(nb, f, ensure_ascii=False, indent=1)
        if n:
            print(f"[slides-only] {path}: {n} cells shown as text")


if __name__ == "__main__":
    main(sys.argv[1:])
